"""Weekly report (Phase 7): week 1 = ET dates 2026-10-20 .. 2026-10-26, generated by the 06:40 ET settle slot on 2026-10-27.

    build_week(archive, ctx, week_no, now, shadow_dir=None) -> dict      (sift.weekly_report.v1)
    markdown(report) -> str
    publish(archive, report, now) -> {"status": ..., "version": n, "paths": [...]}   (idempotent: a new version only if content changed)
    run_due(archive, ctx, now, shadow_dir=None) -> list of publish results (every week that has started and is not yet FINAL)

Status: `PRELIMINARY` until the week is over AND every started game has its outcome, team outcome and settled paper decisions; then `FINAL`.
A `FINAL` report is re-issued as `FINAL` (new version) if a later correction changes its numbers. Only genuine prospective records count
(replay and pre-2026-10-20 records are excluded everywhere; the integrity section says how many were excluded). Sections are independent:
a failure in one is reported as `SECTION_ERROR` with the exception text and never aborts the report.

Locations (projection-data branch, rewritable views + immutable versions):
    reports/nba/week<N>/report.json | report.md | tables/*.csv     latest view
    reports/nba/week<N>/versions/v<NNN>.json | v<NNN>.md            immutable history (never rewritten)
    reports/nba/latest.json                                       index of all weeks (status, version, generated_utc, headline)
"""
from __future__ import annotations

import csv
import hashlib
import json
import os
from datetime import date, datetime, timedelta
from typing import Any, Callable

from ..live.sources import iso
from . import control as CTL, integrity as IG, promotion as PR, schema as S

WEEK1_START_ET = date(2026, 10, 20)
SEASON_OPENER_UTC = S.PROSPECTIVE_START_UTC


def week_window(n: int) -> tuple[str, str]:
    s = WEEK1_START_ET + timedelta(days=7 * (n - 1))
    return s.isoformat(), (s + timedelta(days=6)).isoformat()


def weeks_started(now: datetime) -> list[int]:
    from zoneinfo import ZoneInfo
    d = now.astimezone(ZoneInfo("America/New_York")).date()
    out, n = [], 1
    while WEEK1_START_ET + timedelta(days=7 * (n - 1)) <= d:
        out.append(n)
        n += 1
    return out


def _section(name: str, fn: Callable[[], Any]) -> Any:
    try:
        return fn()
    except Exception as e:  # noqa: BLE001  (a section failure must never hide the others)
        return {"status": "SECTION_ERROR", "section": name, "error": f"{type(e).__name__}: {e}"[:300]}


def _digest(rep: dict) -> str:
    d = json.loads(json.dumps(rep, default=str))
    for k in ("generated_utc", "report_version", "runtime_s"):
        d.pop(k, None)
    return hashlib.sha256(json.dumps(d, sort_keys=True).encode()).hexdigest()


def build_week(archive: str, ctx: str, n: int, now: datetime, shadow_dir: str | None = None, season_types=("regular",)) -> dict[str, Any]:
    from . import diagnostics as DG, evaluate as EV        # imported lazily: a missing optional module degrades one section
    start, end = week_window(n)
    integrity = _section("data_integrity", lambda: IG.build(archive, ctx, start, end, now, season_types))
    ev = _section("evaluation", lambda: EV.week_scorecard(archive, start, end, now))
    complete = (isinstance(integrity, dict) and integrity.get("n_games")
                and integrity["n_started"] == integrity["n_games"] and integrity["n_complete"] == integrity["n_games"])
    over = now.astimezone(IG_ET()).date() > date.fromisoformat(end)
    status = "FINAL" if (complete and over) else "PRELIMINARY"
    sections = {
        "1_data_integrity": integrity,
        "2_projection_performance": _pick(ev, "projection"),
        "3_market_comparison": _pick(ev, "market_comparison"),
        "4_paper_trading": _pick(ev, "paper"),
        "5_market_families": _pick(ev, "families"),
        "6_timing": _pick(ev, "timing"),
        "7_player_matchup_diagnostics": _pick(ev, "segments"),
        "8_patterns": _section("patterns", lambda: DG.ranked_hypotheses(archive, now, window=(start, end))),
        "9_root_cause": _section("root_cause", lambda: DG.root_cause(archive, now, window=(start, end))),
    }
    counts = (ev or {}).get("counts") if isinstance(ev, dict) else None
    rep = {"schema": S.REPORT_SCHEMA, "authority": "research_only", "paper": True, "sport": "NBA", "report_id": f"nba_week{n}",
           "week": {"n": n, "start_et": start, "end_et": end}, "status": status, "generated_utc": iso(now),
           "prospective_only": True, "prospective_start_utc": SEASON_OPENER_UTC, "counts": counts,
           "sections": sections, "control": CTL.latest(shadow_dir),
           "gates": _section("gates", lambda: _gates(ev, n, integrity)),
           "banners": _banners(integrity, counts, status), "methods": _methods()}
    sections["10_next_week_plan"] = _section("next_week_plan", lambda: _plan(rep))
    return rep


def IG_ET():
    from zoneinfo import ZoneInfo
    return ZoneInfo("America/New_York")


def _pick(ev: Any, key: str) -> Any:
    if isinstance(ev, dict) and ev.get("status") == "SECTION_ERROR":
        return ev
    if isinstance(ev, dict) and key in ev:
        return ev[key]
    return {"status": "NO_DATA", "reason": f"evaluation produced no `{key}` block"}


def _banners(integrity: Any, counts: Any, status: str) -> list[str]:
    b = []
    if status != "FINAL":
        b.append("PRELIMINARY: the week is not over or settlements/outcomes are incomplete; numbers will change.")
    ng = (counts or {}).get("n_games") if isinstance(counts, dict) else None
    b.append(f"SAMPLE SIZE: {ng if ng is not None else 'unknown'} independent games in this report. Week-1 evidence cannot establish "
             "profitability: the preregistered control needs >= 200 independent decisions across >= 40 games with positive clustered "
             "lower confidence bounds before any VALIDATED_VALUE language is allowed.")
    b.append("NO BETTING AUTHORITY: nothing in this report authorises a wager, a stake change or a model promotion. All trades are paper.")
    return b


def _gates(ev: Any, n: int, integrity: Any) -> dict:
    cand = {}
    if isinstance(ev, dict) and isinstance(ev.get("paper"), dict):
        cand = ev["paper"].get("by_strategy") or {}
    days = 7 if n >= 1 else 0
    out = {}
    for sid, summ in cand.items():
        if sid in ("NO_BET_V1", "MARKET_ONLY_V1"):
            continue
        out[sid] = PR.weekly_gate({**(summ if isinstance(summ, dict) else {}), "strategy_id": sid, "days_of_evidence": days if n > 1 else 0})
    return out


def _plan(rep: dict) -> dict:
    """Next-week research plan: prioritised, testable, with acceptance criteria. Built from the findings of THIS report only."""
    items = []
    sec = rep["sections"]
    integ = sec["1_data_integrity"] if isinstance(sec["1_data_integrity"], dict) else {}
    miss = integ.get("missing_counts") or {}
    if miss:
        items.append({"priority": 1, "class": "OPERATIONAL_DEFECT", "item": "close evidence gaps found in the data-integrity table",
                      "detail": miss, "acceptance": "next week: every started game has forecast, availability, game forecast, T-60 snapshot, "
                                                     "decisions, outcome, team outcome and paper settlement (0 missing)"})
    hyp = sec.get("8_patterns")
    for h in (hyp.get("ranked") or []) if isinstance(hyp, dict) else []:
        items.append({"priority": 2, "class": h.get("finding_class", "INCONCLUSIVE"), "item": h.get("hypothesis"),
                      "required_prospective_sample": h.get("required_prospective_sample"), "acceptance": h.get("acceptance")})
    rc = sec.get("9_root_cause")
    for r in (rc.get("ranked_causes") or [])[:3] if isinstance(rc, dict) else []:
        items.append({"priority": 3, "class": "PROJECTION_CALIBRATION_ISSUE", "item": r.get("cause"), "acceptance": r.get("acceptance")})
    if not items:
        items.append({"priority": 1, "class": "INCONCLUSIVE", "item": "keep collecting; no testable lead survived the sample-size floor",
                      "acceptance": "n_games >= 40 and >= 200 independent decisions per candidate strategy"})
    for i, it in enumerate(items, 1):
        it["rank"] = i
    return {"items": items, "rule": "ranked by class (operational defects first), then magnitude x repeatability / uncertainty; no parameter change "
                                    "is proposed from one week of data"}


def _methods() -> dict:
    return {"independent_unit": "game (cluster); player-game secondary; contracts, snapshots, YES/NO complements and ladder rungs are never "
                                "treated as independent",
            "bootstrap": {"replicates": 2000, "seed": 20261020, "cluster": "game"},
            "paper_trading": "docs/research/PAPER_ENGINE_SPEC.md", "point_in_time": "forecasts/availability/boards as observed at the decision instant",
            "multiple_testing": "Holm on the declared confirmatory family, Benjamini-Hochberg q=0.10 for exploratory screens",
            "dnp": "player-prop DNP settles at the pre-game fair price (scalar), not NO and not a fee-free void"}


# ------------------------------------------------------------------------------------------------------------------------ rendering
def markdown(rep: dict) -> str:
    L = [f"# NBA research report: week {rep['week']['n']} ({rep['week']['start_et']} .. {rep['week']['end_et']} ET)", "",
         f"**Status: {rep['status']}** (version {rep.get('report_version', '?')}, generated {rep['generated_utc']}). Research / paper only.", ""]
    L += [f"> {b}" for b in rep["banners"]] + [""]
    c = rep.get("counts") or {}
    if c:
        L += ["| independent games | player-games | theses | decisions | contracts |", "|---|---|---|---|---|",
              f"| {c.get('n_games')} | {c.get('n_player_games')} | {c.get('n_theses')} | {c.get('n_decisions')} | {c.get('n_contracts')} |", ""]
    for key, sec in rep["sections"].items():
        title = key.split("_", 1)[1].replace("_", " ").capitalize()
        L += [f"## {key.split('_', 1)[0]}. {title}", ""]
        if key == "1_data_integrity" and isinstance(sec, dict) and "games" in sec:
            L.append(IG.markdown(sec))
        else:
            L.append(_render(sec))
        L.append("")
    L += ["## Control and gates", "", "```json", json.dumps({"control": rep["control"], "gates": rep["gates"]}, indent=1, default=str)[:6000], "```", ""]
    L += ["## Methods", "", "```json", json.dumps(rep["methods"], indent=1), "```"]
    return "\n".join(L) + "\n"


def _render(sec: Any) -> str:
    if isinstance(sec, dict) and isinstance(sec.get("markdown"), str):
        return sec["markdown"]
    txt = json.dumps(sec, indent=1, default=str, sort_keys=True)
    return "```json\n" + (txt if len(txt) < 12000 else txt[:12000] + "\n... (truncated; see report.json)") + "\n```"


# ------------------------------------------------------------------------------------------------------------------------ publishing
def _tables(rep: dict) -> dict[str, list[dict]]:
    t: dict[str, list[dict]] = {}
    integ = rep["sections"].get("1_data_integrity")
    if isinstance(integ, dict) and integ.get("games"):
        t["integrity_games"] = [{k: (json.dumps(v) if isinstance(v, (dict, list)) else v) for k, v in g.items()} for g in integ["games"]]
    for key, sec in rep["sections"].items():
        if isinstance(sec, dict):
            for name, rows in (sec.get("tables") or {}).items():
                if isinstance(rows, list) and rows and isinstance(rows[0], dict):
                    t[f"{key.split('_', 1)[0]}_{name}"] = rows
    return t


def publish(archive: str, rep: dict, now: datetime) -> dict[str, Any]:
    base = os.path.join(archive, "reports", "nba", f"week{rep['week']['n']}")
    ver_dir = os.path.join(base, "versions")
    os.makedirs(ver_dir, exist_ok=True)
    dig = _digest(rep)
    latest_path = os.path.join(base, "report.json")
    prev_ver, prev_dig = 0, None
    if os.path.exists(latest_path):
        prev = json.load(open(latest_path))
        prev_ver, prev_dig = int(prev.get("report_version", 0)), prev.get("content_digest")
    if prev_dig == dig:
        return {"week": rep["week"]["n"], "status": rep["status"], "version": prev_ver, "action": "unchanged", "paths": []}
    ver = prev_ver + 1
    rep = {**rep, "report_version": ver, "content_digest": dig}
    md = markdown(rep)
    paths = []
    for name, body in ((f"v{ver:03d}.json", json.dumps(rep, indent=1, sort_keys=True, default=str)), (f"v{ver:03d}.md", md)):
        p = os.path.join(ver_dir, name)
        with open(p, "x") as f:
            f.write(body)
        paths.append(p)
    with open(latest_path, "w") as f:
        json.dump(rep, f, indent=1, sort_keys=True, default=str)
    with open(os.path.join(base, "report.md"), "w") as f:
        f.write(md)
    tdir = os.path.join(base, "tables")
    os.makedirs(tdir, exist_ok=True)
    for name, rows in _tables(rep).items():
        cols = sorted({k for r in rows for k in r})
        with open(os.path.join(tdir, f"{name}.csv"), "w", newline="") as f:
            w = csv.DictWriter(f, fieldnames=cols)
            w.writeheader()
            w.writerows(rows)
    _update_index(archive, rep, now)
    return {"week": rep["week"]["n"], "status": rep["status"], "version": ver, "action": "written", "paths": paths}


def _update_index(archive: str, rep: dict, now: datetime) -> None:
    p = os.path.join(archive, "reports", "nba", "latest.json")
    idx = json.load(open(p)) if os.path.exists(p) else {"schema": "sift.weekly_report_index.v1", "weeks": {}}
    idx["weeks"][str(rep["week"]["n"])] = {"report_id": rep["report_id"], "status": rep["status"], "version": rep["report_version"],
                                           "generated_utc": rep["generated_utc"], "window": rep["week"], "counts": rep.get("counts"),
                                           "path": f"reports/nba/week{rep['week']['n']}/report.md"}
    idx["updated_utc"] = iso(now)
    idx["authority"] = "research_only"
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "w") as f:
        json.dump(idx, f, indent=1, sort_keys=True)


def run_due(archive: str, ctx: str, now: datetime, shadow_dir: str | None = None) -> list[dict[str, Any]]:
    """Weekly report stage: every week that has started and is not already FINAL-and-unchanged gets a (new version of a) report."""
    out = []
    for n in weeks_started(now):
        rep = build_week(archive, ctx, n, now, shadow_dir)
        out.append(publish(archive, rep, now))
    return out
